var SPL=[{"src":"species","owner":"Avia-Ra","feature":"Blessings of the Sun","n":"Blessings: Bless","lvl":3,"max":1,"reset":"long","tag":"1/Long Rest spell"},{"src":"species","owner":"Avia-Ra","feature":"Blessings of the Sun","n":"Blessings: Lesser Restoration","lvl":5,"max":1,"reset":"long","tag":"1/Long Rest spell"},{"src":"species","owner":"Avia-Ra","feature":"Zealous","n":"Zealous","lvl":1,"max":1,"reset":"long","tag":"Reaction"},{"src":"species","owner":"Elf (Fey)","feature":"Elven Lineage (Fey)","n":"Fey Lineage: Disguise Self","lvl":3,"max":1,"reset":"long","tag":"1/Long Rest spell"},{"src":"species","owner":"Elf (Fey)","feature":"Elven Lineage (Fey)","n":"Fey Lineage: Suggestion","lvl":5,"max":1,"reset":"long","tag":"1/Long Rest spell"},{"src":"species","owner":"Gnome (Star)","feature":"Gnomish Lineage (Star)","n":"Scrap Device","lvl":1,"max":"pb","reset":"long","tag":"1 minute"},{"src":"species","owner":"Orc","feature":"Follow Through","n":"Follow Through","lvl":1,"max":"pb","reset":"long","tag":"Special"},{"src":"species","owner":"Wrothian","feature":"Psionic Blast","n":"Psionic Blast","lvl":1,"max":"pb","reset":"long","tag":"Attack action"}];
